def solve(N, numbers):
    operations = []
    while len(numbers) > 1:
        x = numbers.pop()
        y = numbers.pop()
        z = x ^ y
        operations.append((x, y, z))
        numbers.append(z)
    return operations

def main():
    T = int(input())
    for _ in range(T):
        N = int(input())
        numbers = list(map(int, input().split()))
        operations = solve(N, numbers)
        print(len(operations))
        for op in operations:
            print(*op)

if __name__ == "__main__":
    main()
